def g(n):
    return 18*n + 9 - 42 * ((n + 1) // 3)

def check_equation(a, b):
    lhs = g(a + g(a) + b) - g(a + b)
    rhs = g(a - b) - g(a - g(a) - b)
    return lhs == rhs

# Check for small values of a and b
all_match = True
for a in range(-10, 11):
    for b in range(-10, 11):
        if not check_equation(a, b):
            all_match = False
            print(f"Failed for a={a}, b={b}")
            break
    if not all_match:
        break

print(f"All match: {all_match}")
if all_match:
    print(f"g(2025) = {g(2025)}")
